def locate(self, node: str, rows: list[dict]) -> dict | None:
    info = self.plan["nodes"][node]
    matches = [row for row in rows if row.get("sessionId") == info["session_id"]]
    if not matches:
        return None
    if len(matches) != 1:
        raise RuntimeError("Ambiguous Claude session identity")
    row = matches[0]
    if row.get("kind") != "background" or Path(row.get("cwd", "")).resolve() != Path(info["worktree"]).resolve():
        raise RuntimeError("Claude session identity/worktree mismatch")
    # Accept only known living terminal states. A completed session may be
    # restarted by `attach`; never silently authorize that here.
    if row.get("state") not in {"idle", "working", "blocked", "done"}:
        raise RuntimeError(f"Session is not attachable: {row.get('state')!r}; reconcile manually")
    if not isinstance(row.get("id"), str) or not row["id"] or row["id"].startswith("-"):
        raise RuntimeError("Missing native Claude background ID")
    return row

